(1374,2882,'Abnormally infrequent menstruation.','en',2,'2026-09-16 21:08:17',NULL,NULL,'4172FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1375,2888,'Fractures of the femur.','en',2,'2026-09-16 21:08:17',NULL,NULL,'4165FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1376,2891,'diarrheal illness, usually due to infection','en',2,'2026-09-16 21:08:18',NULL,NULL,'151FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
