(1390,2923,'Inflammation of the lining of the abdomen and pelvis.','en',2,'2026-09-16 21:08:19',NULL,NULL,'3953FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1391,2924,'A major deviation from normal patterns of behavior.','en',2,'2026-09-16 21:08:19',NULL,NULL,'3950FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
