INSERT INTO `scheduler_task_config` VALUES
(2,'Auto Close Visits Task','Stops all active visits that match the visit type(s) specified by the value of the global property \'visits.autoCloseVisitType\'','org.openmrs.scheduler.tasks.AutoCloseVisitsTask','2011-11-28 23:59:59','MM/dd/yyyy HH:mm:ss',86400,0,0,1,'2018-06-04 18:30:16',NULL,NULL,NULL,'8c17b376-1a2b-11e1-a51a-00248140a5eb'),
(4,'Stock Rules Evaluation Job','Checks the stock rules against the item quantity and notifies when quantity is at or below threshold','org.openmrs.module.stockmanagement.api.jobs.StockRuleEvaluationJob','2022-10-01 00:59:59','MM/dd/yyyy HH:mm:ss',86400,0,1,1,'2026-09-16 21:03:08',NULL,NULL,NULL,'5a0b041a-5796-11ed-a495-00155dc81c72'),
(5,'Stock Batch Expiry Job','Checks for stock items expiring soon and notifies inventory manager and clerk','org.openmrs.module.stockmanagement.api.jobs.StockBatchExpiryJob','2022-10-01 00:00:00','MM/dd/yyyy HH:mm:ss',86400,0,1,1,'2026-09-16 21:03:08',NULL,NULL,NULL,'911fc382-5797-11ed-a495-00155dc81c72'),
(6,'Asynchronous Report Generation And Batch Jobs','Runs report generation and batch jobs asynchronously','org.openmrs.module.stockmanagement.api.jobs.AsyncTasksBatchJob','2022-10-01 00:59:59','MM/dd/yyyy HH:mm:ss',60,1,0,1,'2026-09-16 21:03:08',2,'2026-09-16 21:37:59','2026-09-16 21:36:59','73eb1d31-6e5e-11ed-9a5b-00155db5005a'),
(7,'Mark Appointment As Missed Task','Mark appointments as missed task','org.openmrs.module.appointments.scheduler.tasks.MarkAppointmentAsMissedTask','2026-09-16 00:00:00','MM/dd/yyyy HH:mm:ss',86400,1,1,1,'2026-09-16 21:03:14',2,'2026-09-17 11:34:55','2026-09-17 11:34:55','0841cca9-b212-11f1-ad9b-f64a144e9772'),
(8,'Mark Appointment As Complete Task','Mark appointments as complete task','org.openmrs.module.appointments.scheduler.tasks.MarkAppointmentAsCompleteTask','2026-09-16 00:00:00','MM/dd/yyyy HH:mm:ss',86400,1,1,1,'2026-09-16 21:03:14',2,'2026-09-17 11:34:55','2026-09-17 11:34:55','0841d147-b212-11f1-ad9b-f64a144e9772'),
(9,'Reminder of scheduled appointment','Reminder of scheduled appointment','org.openmrs.module.appointments.scheduler.tasks.ReminderForAppointment','2026-09-16 00:00:00','MM/dd/yyyy HH:mm:ss',3600,1,1,1,'2026-09-16 21:03:14',2,'2026-09-17 17:00:00','2026-09-17 17:00:00','0841face-b212-11f1-ad9b-f64a144e9772');
INSERT INTO `serialized_object` VALUES
(1,'Patient Identifier Sticker','','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.report.definition.ReportDefinition id=\"1\" uuid=\"08e2d4eb-91f7-4067-a0c9-025af2122686\" retired=\"false\">\n  <name>Patient Identifier Sticker</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"A4F30A1B-5EB9-11DF-A648-37A07F9C90FB\"/>\n  <dateCreated id=\"3\">2026-09-16 21:33:25 UTC</dateCreated>\n  <parameters id=\"4\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"5\">\n      <name>patientUuid</name>\n      <label>Patient UUID</label>\n      <type>java.lang.String</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <dataSetDefinitions class=\"linked-hash-map\" id=\"6\">\n    <entry>\n      <string>fields</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"7\">\n        <parameterizable class=\"org.openmrs.module.patientdocuments.library.PatientIdStickerDataSetDefinition\" id=\"8\" retired=\"false\">\n          <parameters reference=\"4\"/>\n        </parameterizable>\n        <parameterMappings id=\"9\">\n          <entry>\n            <string>patientUuid</string>\n            <string>${patientUuid}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n  </dataSetDefinitions>\n</org.openmrs.module.reporting.report.definition.ReportDefinition>','2026-09-16 21:33:25',2,NULL,NULL,0,NULL,NULL,NULL,'08e2d4eb-91f7-4067-a0c9-025af2122686'),
(2,'Generic Encounter PDF Report','Dynamically generates PDF printouts for one or more clinical encounters based on O3 forms.','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.report.definition.ReportDefinition id=\"1\" uuid=\"0e89ec4c-10bb-11f1-a6da-0242ac1e0002\" retired=\"false\">\n  <name>Generic Encounter PDF Report</name>\n  <description>Dynamically generates PDF printouts for one or more clinical encounters based on O3 forms.</description>\n  <creator id=\"2\" uuid=\"A4F30A1B-5EB9-11DF-A648-37A07F9C90FB\"/>\n  <dateCreated id=\"3\">2026-09-16 21:33:25 UTC</dateCreated>\n  <parameters id=\"4\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"5\">\n      <name>encounterUuids</name>\n      <label>Encounter UUIDs (comma separated)</label>\n      <type>java.lang.String</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>locale</name>\n      <label>Locale</label>\n      <type>java.util.Locale</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n</org.openmrs.module.reporting.report.definition.ReportDefinition>','2026-09-16 21:33:25',2,NULL,NULL,0,NULL,NULL,NULL,'0e89ec4c-10bb-11f1-a6da-0242ac1e0002');
